const PHRASES = [
  'async remote', 'asynchronous remote', 'worldwide remote', 'global remote', 'work from anywhere',
  'remote data analyst', 'remote data scientist', 'remote ai marketing', 'remote marketing analyst',
  'remote growth analyst', 'remote bi analyst', 'remote automation specialist', 'remote ai workflow consultant'
];
const REMOTE_TOKENS = ['remote', 'async', 'asynchronous', 'worldwide', 'anywhere', 'global', 'distributed'];
const ROLE_TOKENS = [
  'data analyst', 'data scientist', 'business intelligence', 'bi analyst', 'marketing analyst',
  'growth analyst', 'automation specialist', 'ai workflow', 'ai marketing', 'performance marketing',
  'martech', 'growth marketing'
];

function isMatch(text) {
  const t = text.toLowerCase();
  if (PHRASES.some(p => t.includes(p))) return true;
  const hasRemoteSignal = REMOTE_TOKENS.some(r => t.includes(r));
  const hasRoleSignal = ROLE_TOKENS.some(r => t.includes(r));
  return hasRemoteSignal && hasRoleSignal;
}

return $input.all().filter(item => {
  const j = item.json;
  return isMatch([j.job_title, j.description, j.tags].join(' '));
});

const existing = $('Read Existing Raw Jobs').all().map(i => i.json);
const seenUrls = new Set(existing.map(e => String(e.job_url || '').trim().toLowerCase()).filter(Boolean));
const seenKeys = new Set(existing.map(e => String(e.company || '').trim().toLowerCase() + '|' + String(e.job_title || '').trim().toLowerCase()));

const out = [];
const seenThisRun = new Set();
const today = new Date().toISOString().slice(0, 10);

for (const item of $input.all()) {
  const j = item.json;
  const url = String(j.job_url || '').trim().toLowerCase();
  const key = String(j.company || '').trim().toLowerCase() + '|' + String(j.job_title || '').trim().toLowerCase();
  if (!url) continue;
  if (seenUrls.has(url) || seenKeys.has(key)) continue;
  if (seenThisRun.has(url) || seenThisRun.has(key)) continue;
  seenThisRun.add(url);
  seenThisRun.add(key);
  out.push({ json: { ...j, job_id: url, date_found: today } });
}
return out;

const REJECT_PATTERNS = [
  'us only', 'u.s. only', 'usa only', 'united states only', 'canada only', 'uk only', 'u.k. only',
  'united kingdom only', 'eu only', 'europe only', 'australia only', 'must be based in',
  'must live in', 'must be authorized to work in', 'local work permit required', 'hybrid',
  'onsite', 'on-site', 'office required', 'remote within', 'fixed us hours', 'fixed eu hours'
];
const KEEP_SIGNALS = [
  'worldwide remote', 'global remote', 'work from anywhere', 'anywhere', 'apac remote',
  'international contractors', 'contractor role', 'b2b contractor', 'hires via deel',
  'hires via remote.com', 'hires via oyster', 'eor supported', 'remote first', 'distributed team'
];

const out = [];
for (const item of $input.all()) {
  const j = item.json;
  const text = [j.job_title, j.location_text, j.description].join(' ').toLowerCase();
  const rejectHit = REJECT_PATTERNS.find(p => text.includes(p));
  const keepHit = KEEP_SIGNALS.find(p => text.includes(p));
  const rejected = Boolean(rejectHit) && !keepHit;
  out.push({ json: {
    ...j,
    _rejected: rejected,
    _reject_reason: rejected ? ('Hard filter: matched "' + rejectHit + '"') : '',
    hard_filter_keep_signal: keepHit || ''
  }});
}
return out;

return $input.all().map(item => ({ json: {
  date_rejected: new Date().toISOString().slice(0, 10),
  job_title: item.json.job_title,
  company: item.json.company,
  job_url: item.json.job_url,
  reason: item.json._reject_reason
}}));

const item = $input.first();
const raw = (item.json.message && item.json.message.content) || item.json.content || item.json.text || '';
let parsed;
try {
  const match = String(raw).match(/\{[\s\S]*\}/);
  parsed = JSON.parse(match ? match[0] : raw);
} catch (e) {
  parsed = {
    taiwan_eligible: 'unclear',
    reason: 'AI response could not be parsed',
    location_risk: 'medium',
    timezone_risk: 'medium',
    contractor_possible: 'unclear',
    decision: 'manual_check'
  };
}
const original = $('Loop Jobs (Split In Batches)').item.json;
return [{ json: { ...original, ...parsed } }];

const KEEP = ['async', 'asynchronous', 'flexible hours', 'flexible schedule', 'distributed team', 'remote first', 'low meeting culture', 'work across time zones'];
const REJECT = ['strict 9 to 5', 'strict 9-to-5', 'fixed us hours', 'fixed est hours', 'fixed pst hours', 'fixed cet hours', 'daily live calls required', 'must overlap full business day'];

const out = [];
for (const item of $input.all()) {
  const j = item.json;
  const text = [j.job_title, j.description, j.tags].join(' ').toLowerCase();
  const rejectHit = REJECT.find(p => text.includes(p));
  const keepHits = KEEP.filter(p => text.includes(p));

  let async_level = 'low';
  if (text.includes('async') || text.includes('asynchronous')) async_level = 'high';
  else if (keepHits.length >= 1) async_level = 'medium';
  if (rejectHit) async_level = 'low';

  out.push({ json: { ...j, async_level, async_reject_hit: rejectHit || '', async_keep_hits: keepHits.join(', ') } });
}
return out;

const PRIMARY = [
  'data analyst', 'data scientist', 'junior data scientist', 'business intelligence analyst', 'bi analyst',
  'marketing analyst', 'performance marketing analyst', 'growth analyst', 'ai marketing specialist',
  'ai automation specialist', 'ai workflow consultant', 'martech analyst', 'creative strategist'
];

const out = [];
for (const item of $input.all()) {
  const j = item.json;
  const text = [j.job_title, j.description, j.tags].join(' ').toLowerCase();
  const hit = PRIMARY.find(p => text.includes(p));
  let role_category = 'other';
  if (hit) role_category = hit;
  else if (/data|analytics|marketing|growth|automation|\bbi\b/.test(text)) role_category = 'adjacent';
  out.push({ json: { ...j, role_category, role_fit_primary: Boolean(hit) } });
}
return out;

const WORLDWIDE_SIGNALS = ['worldwide remote', 'global remote', 'work from anywhere', 'anywhere',
  'international contractors', 'contractor role', 'b2b contractor', 'hires via deel', 'hires via remote.com',
  'hires via oyster', 'eor supported'];

const out = [];
for (const item of $input.all()) {
  const j = item.json;
  const text = [j.job_title, j.description, j.tags].join(' ').toLowerCase();
  const kept = String(j.hard_filter_keep_signal || '').toLowerCase();

  let taiwanScore = 0;
  if (j.location_risk === 'high' || j.taiwan_eligible === 'no') {
    taiwanScore = 0;
  } else if (WORLDWIDE_SIGNALS.some(s => kept.includes(s)) || j.taiwan_eligible === 'yes') {
    taiwanScore = 40;
  } else if (kept.includes('apac remote')) {
    taiwanScore = 30;
  } else if (j.taiwan_eligible === 'unclear') {
    taiwanScore = 20;
  }

  let asyncScore = 0;
  if (j.async_level === 'high') asyncScore = 25;
  else if (text.includes('flexible hours') || text.includes('flexible schedule')) asyncScore = 20;
  else if (text.includes('distributed team')) asyncScore = 15;
  else if (text.includes('remote first')) asyncScore = 10;

  const roleScore = j.role_fit_primary ? 25 : (j.role_category === 'adjacent' ? 15 : 0);

  const salaryText = String(j.salary || '');
  const nums = (salaryText.match(/\d[\d,]*/g) || []).map(n => parseInt(n.replace(/,/g, ''), 10));
  const maxSalary = nums.length ? Math.max(...nums) : 0;
  let salaryScore = 0;
  if (maxSalary >= 5000) salaryScore = 25;
  else if (maxSalary >= 3000) salaryScore = 15;
  else if (salaryText) salaryScore = 10;

  const score = Math.min(100, taiwanScore + asyncScore + roleScore + salaryScore);

  out.push({ json: { ...j, taiwan_score: taiwanScore, async_score: asyncScore, role_score: roleScore, salary_score: salaryScore, score } });
}
return out;

return $input.all().map(item => {
  const j = item.json;
  return { json: {
    date_rejected: new Date().toISOString().slice(0, 10),
    job_title: j.job_title,
    company: j.company,
    job_url: j.job_url,
    reason: 'Score ' + j.score + '/100 below 70 threshold (taiwan_eligible=' + j.taiwan_eligible + ', async_level=' + j.async_level + ', role_category=' + j.role_category + ')'
  }};
});

const out = [];
for (const item of $input.all()) {
  const j = item.json;
  let application_status = 'manual_check';

  if (j.taiwan_eligible === 'yes' && j.score >= 85 &&
      (j.async_level === 'high' || j.async_level === 'medium') &&
      j.location_risk === 'low' &&
      (j.timezone_risk === 'low' || j.timezone_risk === 'medium')) {
    application_status = 'ready_to_apply';
  } else if (j.taiwan_eligible === 'no' || j.location_risk === 'high' || j.timezone_risk === 'high' || j.score < 70) {
    application_status = 'reject';
  } else if (j.taiwan_eligible === 'unclear' && j.score >= 85 && j.location_risk === 'medium') {
    application_status = 'manual_check';
  }

  const passes_one_sentence_rule = j.taiwan_eligible === 'yes' && j.location_risk !== 'high' && j.timezone_risk !== 'high';

  out.push({ json: { ...j, application_status, passes_one_sentence_rule } });
}
return out;

return $input.all().map(item => {
  const j = item.json;
  const whyGoodFit = [];
  if (j.role_fit_primary) whyGoodFit.push('Strong role match (' + j.role_category + ')');
  if (j.async_level === 'high') whyGoodFit.push('Clearly async');
  if (j.salary) whyGoodFit.push('Salary listed: ' + j.salary);
  if (j.taiwan_eligible === 'yes') whyGoodFit.push('Taiwan eligible: ' + j.reason);

  return { json: {
    date_found: j.date_found,
    score: j.score,
    job_title: j.job_title,
    company: j.company,
    job_url: j.job_url,
    salary: j.salary,
    taiwan_eligible: j.taiwan_eligible,
    taiwan_reason: j.reason,
    location_risk: j.location_risk,
    timezone_risk: j.timezone_risk,
    contractor_possible: j.contractor_possible,
    async_level: j.async_level,
    role_category: j.role_category,
    why_good_fit: whyGoodFit.join('; '),
    decision: j.decision,
    application_status: j.application_status,
    notes: ''
  }};
});

