const item = $input.first();
const raw = (item.json.message && item.json.message.content) || item.json.content || item.json.text || '';
const original = $('IF Score >= 85 (Top Job)').item.json;
return [{ json: {
  job_url: original.job_url,
  notes: 'Cover letter draft:\n\n' + raw,
  application_status: original.application_status
} }];

const today = new Date().toISOString().slice(0, 10);
const filtered = $('Read Today\'s Filtered Jobs').all().map(i => i.json).filter(j => j.date_found === today);
const rejected = $('Read Today\'s Rejected Jobs').all().map(i => i.json).filter(j => j.date_rejected === today);

const top = filtered
  .filter(j => j.application_status !== 'reject')
  .sort((a, b) => (Number(b.score) || 0) - (Number(a.score) || 0))
  .slice(0, 10);
const manualCheck = filtered.filter(j => j.taiwan_eligible === 'unclear' && (Number(j.score) || 0) >= 70);

function countReason(keyword) {
  return rejected.filter(r => String(r.reason || '').toLowerCase().includes(keyword)).length;
}

const lines = [];
lines.push('Daily Taiwan Eligible Async Remote Jobs');
lines.push('');
lines.push('Top jobs today:');
lines.push('');
if (top.length) {
  top.forEach((j, idx) => {
    lines.push((idx + 1) + '. ' + j.job_title);
    lines.push('Company: ' + j.company);
    lines.push('Score: ' + j.score);
    lines.push('Taiwan eligible: ' + j.taiwan_eligible);
    lines.push('Reason: ' + j.taiwan_reason);
    lines.push('Async level: ' + j.async_level);
    lines.push('Timezone risk: ' + j.timezone_risk);
    lines.push('Salary: ' + (j.salary || 'Not listed'));
    lines.push('Why it fits Jerry: ' + j.why_good_fit);
    lines.push('Apply link: ' + j.job_url);
    lines.push('');
  });
} else {
  lines.push('(No jobs scored 70+ today.)');
  lines.push('');
}

lines.push('Manual check:');
if (manualCheck.length) {
  manualCheck.forEach(j => lines.push('- ' + j.job_title + ' at ' + j.company + ' (score ' + j.score + ') - ' + j.job_url));
} else {
  lines.push('(None.)');
}
lines.push('');

lines.push('Rejected summary:');
lines.push('US/Canada/UK/EU/Australia only: ' + countReason('only'));
lines.push('Hybrid/onsite: ' + (countReason('hybrid') + countReason('onsite')));
lines.push('Timezone risk: ' + countReason('timezone'));
lines.push('Low score: ' + countReason('below 70'));
lines.push('Total rejected today: ' + rejected.length);

return [{ json: { digest_text: lines.join('\n'), top_count: top.length, rejected_count: rejected.length } }];
